        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # None means no prerelease

    @classmethod
    def parse(cls, s: str) -> 'SemVer':
        m = _VERSION_RE.match(s)
        if not m:
            raise ValueError(f"malformed version: {s!r}")
        major = int(m.group(1))
        minor = int(m.group(2))
        patch = int(m.group(3))
        pre = m.group(4)
        # build = m.group(5)  # ignored
        prerelease = None
        if pre is not None:
            parts = pre.split('.')
            for p in parts:
                if not _IDENT_RE.match(p):
                    raise ValueError(f"malformed prerelease identifier: {p!r}")
            prerelease = tuple(parts)
        return cls(major, minor, patch, prerelease)

    def _key(self):
        # For comparison: no prerelease > any prerelease
        if self.prerelease is None:
            pre_key = (1,)  # greater than any prerelease tuple
        else:
            pre_key = (0,) + tuple(
                (0, int(p)) if p.isdigit() else (1, p)
                for p in self.prerelease
            )
        return (self.major, self.minor, self.patch, pre_key)

