def _numeric_key(digits):
    # Avoid Python's decimal-to-int digit limit.
    digits = digits.lstrip("0") or "0"
    return len(digits), digits


def _precedence_key(core, prerelease=None):
    identifiers = ()
    if prerelease is not None:
        identifiers = tuple(
            (0, _numeric_key(identifier))
            if identifier.isdigit()
            else (1, identifier)
            for identifier in prerelease.split(".")
        )
    return (
        tuple(_numeric_key(component) for component in core),
        prerelease is None,
        identifiers,
    )


def _parse_version(text):
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"Malformed version: {text!r}")
    major, minor, patch, prerelease = match.groups()
    core = (major, minor, patch)
    return core, _precedence_key(core, prerelease)


def _increment(digits):
    prefix = digits.rstrip("9")
    trailing_zeros = "0" * (len(digits) - len(prefix))
    if not prefix:
        return "1" + trailing_zeros
    return prefix[:-1] + chr(ord(prefix[-1]) + 1) + trailing_zeros


def satisfies(version: str, range_expr: str) -> bool:
    """Compare a version against a fully validated semantic-version range."""
    _, candidate = _parse_version(version)
    range_matches = False

    # Validate every comparator, even after the result is already known.
    for comparator_set in range_expr.split("||"):
        tokens = comparator_set.split()
        if not tokens:
            raise ValueError("Range contains an empty comparator set")

        set_matches = True
        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError(f"Malformed comparator: {token!r}")

            operator, text = match.groups()
            operator = operator or "="
            core, target = _parse_version(text)

            if operator in ("^", "~"):
                major, minor, patch = core
                if operator == "~":
                    upper_core = (major, _increment(minor), "0")
                elif major != "0":
                    upper_core = (_increment(major), "0", "0")
                elif minor != "0":
                    upper_core = ("0", _increment(minor), "0")
                else:
                    upper_core = ("0", "0", _increment(patch))

                matches = target <= candidate < _precedence_key(upper_core)
            elif operator == "=":
                matches = candidate == target
            elif operator == ">":
                matches = candidate > target
            elif operator == ">=":
                matches = candidate >= target
            elif operator == "<":
                matches = candidate < target
            else:  # <=
                matches = candidate <= target

            set_matches = set_matches and matches

        range_matches = range_matches or set_matches

    return range_matches
